class _ExponentialBackoff(object):
    # These values lead to:
    #  - 25 calls in the first 20 seconds
    #  - Overhead overall remains below 10%
    #  - After 1 minute, the interval is 5 seconds

    def __init__(self, initial_time_ms=200, max_time_ms=15000, factor=1.1):
        self.initial_time_ms = initial_time_ms
        self.last_time = None
        self.max_time_ms = max_time_ms
        self.factor = factor

    def next_sleep_time(self):
        if self.last_time is None:
            next_time = self.initial_time_ms
        else:
            next_time = self.last_time * self.factor
        if next_time > self.max_time_ms:
            next_time = self.max_time_ms

        self.last_time = next_time

        return next_time

    def sleep_next(self):
        sleep_time = float(self.next_sleep_time()) / 1000.0
        #print("Sleeping %.3f" % sleep_time)
        time.sleep(sleep_time)

def run_workflow_definition(cls, name, prompts=None):
    """Runs specific Workflow Processes Definitions.

    Parameters
    ----------
    name : str
        Name or ID of an enabled workflow to execute
    prompts : dict, optional
        Input values to provide for the initial workflow prompts.  Should be
        specified as name:value pairs.

    Returns
    -------
    RestObj
        The executing workflow

    """
    workflow = cls._find_specific_workflow(name)
    if workflow is None:
        raise ValueError("No Workflow enabled for %s name or id." % name)

    if prompts is None:
        return cls.post(
            "/processes?definitionId=" + workflow["id"],
            headers={"Content-Type": "application/vnd.sas.workflow.variables+json"},
        )
    if isinstance(prompts, dict):
        variables = []

        # For each prompt defined in the workflow, check if a value was provided.
        for prompt in workflow.prompts:
            if prompt["variableName"] in prompts:
                name = prompt["variableName"]
                value = prompts[name]

                if type(value) == datetime.datetime:
                    # NOTE: do not use isinstance() to compare types as
                    # datetime.date will also evaluate as True.

                    # Explicitly convert to local time zone if not set.
                    if value.tzinfo is None:
                        try:
                            value = value.astimezone()
                        except OSError:
                            # On Windows pre-1970 dates will cause an issue.
                            # See https://bugs.python.org/issue36759
                            pass

                    if value.tzinfo is None:
                        # Failed to convert to local time.  Have to just assume it's UTC.
                        # Example: 2023-01-25T13:49:40.726162Z
                        value = value.isoformat() + "Z"
                    else:
                        # Example: 2023-01-25T13:49:40.726162-05:00
                        value = value.isoformat()

                variables.append(
                    {
                        "name": name,
                        "value": value,
                        "scope": "local",
                        "type": prompt["variableType"],
                        "version": prompt["version"],
                    }
                )

        return cls.post(
            "/processes?definitionId=" + workflow["id"],
            json={"variables": variables},
            headers={"Content-Type": "application/vnd.sas.workflow.variables+json"},

def request(cls, verb, path, session=None, format_="auto", **kwargs):
    """Send an HTTP request with a session.

    Parameters
    ----------
    verb : str
        A valid HTTP request verb.
    path : str
        Path portion of URL to request.  Assumed to be relative to
        `_SERVICE_ROOT`.
    session : Session, optional
        Defaults to `current_session()`.
    format_ : {'auto', 'response', 'content', 'json', 'text'}
        The format of the return response.  Defaults to `auto`.
        response: the raw `Response` object.
        content: Response.content
        json: Response.json()
        text: Response.text
        auto: `RestObj` constructed from JSON if possible, otherwise same as
              `text`.
    **kwargs
        Additional arguments are passed to the session `request` method.

    Returns
    -------

    """
    if path.startswith("/"):
        path = cls._SERVICE_ROOT + path
    else:
        path = cls._SERVICE_ROOT + "/" + path

    return core.request(verb, path, session, format_, **kwargs)

