#'
#' @param task A Task object
#' @param wait The interval to wait between polling
#' @param callback A function to be called for each message received. Set to NULL for no callback
#'
#' @return Task The Task object that was input
#'
#' @family deployment functions
#' @export
poll_task <- function(task, wait = 1, callback = message) {
  validate_R6_class(task, c("Task", "ContentTask", "VariantTask"))
  con <- task$connect

  all_task_data <- list()

  finished <- FALSE
  code <- -1
  first <- 0
  while (!finished) {
    task_data <- con$task(task$get_task()$task_id, wait = wait, first = first)
    finished <- task_data[["finished"]]
    code <- task_data[["code"]]
    first <- task_data[["last"]]

    if (!is.null(callback)) {
      lapply(task_data[["output"]], callback)
    }
    all_task_data <- c(all_task_data, task_data[["output"]])
  }

  if (code != 0) {
    msg <- task_data[["error"]]
    # print the logs if there is no callback
    if (is.null(callback)) {
      lapply(all_task_data, message)
    }
    stop(msg)
  }
  if (!is.null(task_data[["result"]])) {
    task$add_data(task_data[["result"]])
  }
  task
}

// The available statuses (or states) of a Job.
const (
	// The job was canceled by the user before it began to run.
	StatusCanceled = "Canceled"

	// The job could not be launched due to an error. This status does not
	// refer to jobs where the process exited with a non-zero exit code.
	StatusFailed = "Failed"

	// The job was launched and finished executing. This includes jobs where
	// the process exited with a non-zero exit code.
	StatusFinished = "Finished"

	// The job was forcibly killed while it was running, i.e. the job
	// process received SIGKILL.
	StatusKilled = "Killed"

	// The job was successfully submitted to the job scheduling system but
	// has not started running yet.
	StatusPending = "Pending"

	// The job is currently running.
	StatusRunning = "Running"

	// The job was running, but execution was paused and may be resumed at a
	// later time.
	StatusSuspended = "Suspended"
)

// TerminalStatus returns true when the passed status is "terminal" -- i.e. the job's status
// will not change in the future.
func TerminalStatus(status string) bool {
	switch status {
	case StatusCanceled, StatusFailed, StatusFinished, StatusKilled:
		return true
	}
	return false
}

